public class DependencyConflictAuditorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static java.util.List<String> deps() {
        return new java.util.ArrayList<>(java.util.Arrays.asList(
                "org.slf4j:slf4j-api:1.7.36",
                "com.google.guava:guava:32.1.2-jre",
                "org.slf4j:slf4j-api:2.0.9",
                "com.google.guava:guava:32.1.2-jre",
                "org.slf4j:slf4j-api:1.7.36",
                "junit:junit",
                "com.fasterxml.jackson.core:jackson-databind:2.15.2"));
    }

    public static void main(String[] args) {
        check("resolved keeps the first version of each artifact",
                "[org.slf4j:slf4j-api:1.7.36, com.google.guava:guava:32.1.2-jre, "
                        + "com.fasterxml.jackson.core:jackson-databind:2.15.2]",
                String.valueOf(DependencyConflictAuditor.resolved(deps())));
        check("conflicts reports only the clashing artifact",
                "[org.slf4j:slf4j-api wants 1.7.36, 2.0.9]",
                String.valueOf(DependencyConflictAuditor.conflicts(deps())));
        java.util.List<String> clean = new java.util.ArrayList<>(java.util.Arrays.asList(
                "a:b:1.0", "c:d:2.0", "a:b:1.0"));
        check("repeating the same version is not a conflict", "[]",
                String.valueOf(DependencyConflictAuditor.conflicts(clean)));
        check("resolved de-duplicates identical entries", "[a:b:1.0, c:d:2.0]",
                String.valueOf(DependencyConflictAuditor.resolved(clean)));
        java.util.List<String> triple = new java.util.ArrayList<>(java.util.Arrays.asList(
                "z:z:3.0", "z:z:1.0", "z:z:2.0", "m:m:9.0", "m:m:8.0"));
        check("three versions are listed in first-seen order",
                "[m:m wants 9.0, 8.0, z:z wants 3.0, 1.0, 2.0]",
                String.valueOf(DependencyConflictAuditor.conflicts(triple)));
        check("resolved on an empty list", "[]",
                String.valueOf(DependencyConflictAuditor.resolved(new java.util.ArrayList<String>())));
        check("conflicts on an empty list", "[]",
                String.valueOf(DependencyConflictAuditor.conflicts(new java.util.ArrayList<String>())));
        finish();
    }
}

