public class DependencyConflictAuditor {

    private static java.util.Map<String, java.util.List<String>> versionsByArtifact(
            java.util.List<String> deps) {
        java.util.Map<String, java.util.List<String>> seen = new java.util.LinkedHashMap<>();
        for (String dep : deps) {
            String[] parts = dep.split(":");
            if (parts.length != 3 || parts[0].isEmpty() || parts[1].isEmpty() || parts[2].isEmpty()) {
                continue;
            }
            String key = parts[0] + ":" + parts[1];
            java.util.List<String> versions = seen.get(key);
            if (versions == null) {
                versions = new java.util.ArrayList<>();
                seen.put(key, versions);
            }
            if (!versions.contains(parts[2])) {
                versions.add(parts[2]);
            }
        }
        return seen;
    }

    public static java.util.List<String> resolved(java.util.List<String> deps) {
        java.util.List<String> result = new java.util.ArrayList<>();
        java.util.Map<String, java.util.List<String>> seen = versionsByArtifact(deps);
        for (java.util.Map.Entry<String, java.util.List<String>> entry : seen.entrySet()) {
            result.add(entry.getKey() + ":" + entry.getValue().get(0));
        }
        return result;
    }

    public static java.util.List<String> conflicts(java.util.List<String> deps) {
        java.util.List<String> result = new java.util.ArrayList<>();
        java.util.Map<String, java.util.List<String>> seen = versionsByArtifact(deps);
        for (java.util.Map.Entry<String, java.util.List<String>> entry : seen.entrySet()) {
            java.util.List<String> versions = entry.getValue();
            if (versions.size() > 1) {
                result.add(entry.getKey() + " wants " + String.join(", ", versions));
            }
        }
        java.util.Collections.sort(result);
        return result;
    }
}
